    11	const getRerenderCount = () => rerenderCount;
    12	const resetRerenderCount = () => {
    13	    rerenderCount = 0;
    14	};
    15	
    16	function IncrementRenderCount() {
    17	    rerenderCount += 1;
    18	    return null;
    19	}
    20	
    21	function ComposerWithSuggestionsE2e(props: ComposerWithSuggestionsProps, ref: ForwardedRef<ComposerRef>) {
    22	    'use no memo';
    23	
    24	    // we rely on waterfall rendering in react, so we intentionally disable compiler
    25	    // for this component. This file is only used for e2e tests, so it's okay to
    26	    // disable compiler for this file.
    27	
    28	    const textInputRef = useRef<ComposerRef | null>();
    29	    const hasFocusBeenRequested = useRef(false);
    30	    const onLayout = useCallback((event: LayoutChangeEvent) => {
    31	        const testConfig = E2EClient.getCurrentActiveTestConfig();
    32	        if (testConfig?.reportScreen && typeof testConfig.reportScreen !== 'string' && !testConfig?.reportScreen.autoFocus) {
    33	            return;
    34	        }
    35	        const canRequestFocus = event.nativeEvent.layout.width > 0 && !hasFocusBeenRequested.current;
    36	        if (!canRequestFocus) {
    37	            return;
    38	        }
    39	
    40	        hasFocusBeenRequested.current = true;
    41	
    42	        const setFocus = () => {
    43	            if (!(textInputRef && 'current' in textInputRef)) {
    44	                return;
    45	            }
    46	
    47	            textInputRef.current?.focus(true);
    48	
    49	            setTimeout(() => {
    50	                // and actually let's verify that the keyboard is visible
    51	                if (Keyboard.isVisible()) {
    52	                    return;
    53	                }
    54	
    55	                textInputRef.current?.blur();
    56	                setFocus();
    57	                // 1000ms is enough time for any keyboard to open
    58	            }, 1000);
    59	        };
    60	
    61	        // Simulate user behavior and don't set focus immediately
    62	        setTimeout(setFocus, 2000);
    63	    }, []);
    64	
    65	    return (
    66	        <ComposerWithSuggestions
    67	            // eslint-disable-next-line react/jsx-props-no-spreading
    68	            {...props}
    69	            ref={(composerRef) => {
    70	                textInputRef.current = composerRef;
    71	
    72	                if (typeof ref === 'function') {
    73	                    ref(composerRef);
    74	                }
    75	            }}
    76	            onLayout={onLayout}
    77	        >
    78	            {/* Important: 
    79	                    this has to be a child, as this container might not
    80	                    re-render while the actual ComposerWithSuggestions will.
    81	            */}
    82	            <IncrementRenderCount />
    83	        </ComposerWithSuggestions>
    84	    );
    85	}
    86	
    87	ComposerWithSuggestionsE2e.displayName = 'ComposerWithSuggestionsE2e';
    88	
    89	export default forwardRef(ComposerWithSuggestionsE2e);
    90	export {getRerenderCount, resetRerenderCount};
